template<>struct Wire<CB_REQUEST> {static Json Encode(const CB_REQUEST& v){Json j=Json::object();j["size"]=EncodeWire(v.size);j["version"]=EncodeWire(v.version);j["device"]=EncodeWire(v.device);j["generation"]=EncodeWire(v.generation);j["offset"]=EncodeWire(v.offset);j["capacity"]=EncodeWire(v.capacity);return j;}static void Decode(const Json& j,CB_REQUEST& v){Require(j.is_object(),"Wire struct must be object");for(auto it=j.begin();it!=j.end();++it){if(it.key()=="size")DecodeWire(it.value(),v.size);else if(it.key()=="version")DecodeWire(it.value(),v.version);else if(it.key()=="device")DecodeWire(it.value(),v.device);else if(it.key()=="generation")DecodeWire(it.value(),v.generation);else if(it.key()=="offset")DecodeWire(it.value(),v.offset);else if(it.key()=="capacity")DecodeWire(it.value(),v.capacity);else throw SdkError(87,"Unknown wire field: "+it.key());}}};
